class Instrument {
  constructor(brand) {
    this.brand = brand;
  }

  play() {
    return `${this.brand} instrument is making a sound.`;
  }
}

class Guitar extends Instrument {
  constructor(brand, strings) {
    super(brand);
    this.strings = strings;
  }

  play() {
    return `The ${this.brand} guitar with ${this.strings} strings is strumming a melody!`;
  }
}

